import requests,concurrent.futures,bs4
urls=['https://pmc.ncbi.nlm.nih.gov/articles/instance/10781646/bin/41586_2023_6816_MOESM5_ESM.xlsx','https://www.immune-dictionary.org','https://www.ebi.ac.uk/europepmc/webservices/rest/PMC10781646/supplementaryFiles','https://api.github.com/search/repositories?q=immune-dictionary']
def f(u):
 try:
  r=requests.get(u,timeout=40)
  if 'supplementaryFiles' in u:open('supplementary.zip','wb').write(r.content);return u,r.status_code,len(r.content),r.headers.get('Content-Type')
  if 'xlsx' in u:open('cytokine_signatures.xlsx','wb').write(r.content);return u,r.status_code,len(r.content),r.headers.get('Content-Type')
  return u,r.status_code,r.text[:16000]
 except Exception as e:return u,str(e)
for x in concurrent.futures.ThreadPoolExecutor().map(f,urls):print(x)
PY"
